PUPPETEER_WACZ_PREVIEW_SCRIPT = """\
const fs = require("node:fs");
const puppeteer = require("puppeteer");
let probePage;
let probeBrowser;
let probeStage = "launch";
const probeConsoleMessages = [];
const probeRequestFailures = [];
const probeDownloads = [];

function isDescendantOf(frame, ancestor) {
  let parent = frame.parentFrame();
  while (parent) {
    if (parent === ancestor) return true;
    parent = parent.parentFrame();
  }
  return false;
}

async function frameText(frame) {
  try {
    return await frame.evaluate(() => {
      const body = document.body ? document.body.innerText : "";
      const root = document.documentElement ? document.documentElement.innerText : "";
      return body || root || "";
    });
  } catch (_error) {
    return "";
  }
}

async function readPreviewText(page, expectedText) {
  const frames = page.frames();
  const previewFrame = frames.find((frame) => {
    const url = frame.url();
    return url.includes("/archivewebpage/archivewebpage.wacz") && url.includes("preview=1");
  });

  const frameState = [];
  for (const frame of frames) {
    if (!previewFrame || !isDescendantOf(frame, previewFrame) || !frame.url().includes("/replay/w/")) continue;
    const text = await frameText(frame);
    frameState.push({
      name: frame.name(),
      url: frame.url(),
      isPreview: frame === previewFrame,
      underPreview: previewFrame ? isDescendantOf(frame, previewFrame) : false,
      textSample: text.slice(0, 240),
    });
    if (text.includes(expectedText)) {
      return {
        matched: true,
        previewUrl: previewFrame.url(),
        matchedFrameUrl: frame.url(),
        matchedFrameName: frame.name(),
        bodyChildren: await frame.evaluate(() => document.body.childElementCount),
        textSample: text.slice(0, 400),
      };
    }
  }
  return {matched: false, frames: frameState};
}


async function main() {
  const config = JSON.parse(fs.readFileSync(0, "utf8"));
  const browser = await puppeteer.launch({
    executablePath: config.chromePath,
    headless: true,
    args: [
      "--no-sandbox",
      "--disable-dev-shm-usage",
      "--disable-background-networking",
    ],
  });
  probeBrowser = browser;
  const downloadSession = await browser.target().createCDPSession();
  await downloadSession.send('Browser.setDownloadBehavior', {behavior: 'default', eventsEnabled: true});
  downloadSession.on('Browser.downloadWillBegin', ({url, suggestedFilename}) => probeDownloads.push({url, suggestedFilename}));

  const page = await browser.newPage();
  probePage = page;
  page.on("console", (message) => {
    probeConsoleMessages.push({type: message.type(), text: message.text()});
  });
  page.on("pageerror", (error) => {
    probeConsoleMessages.push({type: "pageerror", text: String(error)});
  });
  page.on("requestfailed", (request) => {
    probeRequestFailures.push({
      url: request.url(),
      error: request.failure() ? request.failure().errorText : "unknown",
    });
  });

  await page.evaluateOnNewDocument(() => {
    window.replayCoverObserved = false;
    window.replayPaintedObserved = false;
    window.addEventListener('message', (event) => {
      if (event.source === document.getElementById('main-frame')?.contentWindow && event.data?.type === 'archivebox-replay-painted') {
        window.replayPaintedObserved = true;
      }
    });
    new MutationObserver((records) => {
      if (records.some((record) => Array.from(record.addedNodes).some((node) => node.id === 'replay-screenshot-cover'))) {
        window.replayCoverObserved = true;
      }
    }).observe(document, {childList: true, subtree: true});
  });
  probeStage = "detail navigation";
  const response = await page.goto(config.detailUrl, {
    waitUntil: "domcontentloaded",
    timeout: 30000,
  });
  probeStage = "preview frame navigation";
  await page.waitForFrame((frame) => {
    const url = frame.url();
    return url.includes("/archivewebpage/archivewebpage.wacz") && url.includes("preview=1");
  });
  probeStage = "screenshot cover dismissal";
  await page.waitForFunction(() =>
    window.replayPaintedObserved && !document.getElementById('replay-screenshot-cover'),
    {polling: 50, timeout: 10000});
  const coverState = await page.evaluate(() => ({
    observed: window.replayCoverObserved,
    dismissed: !document.getElementById('replay-screenshot-cover'),
    screenshot: !!document.querySelector('.thumb-card[data-plugin-name="screenshot"] iframe'),
  }));
  probeStage = "captured page content";
  const previewResult = await readPreviewText(page, config.expectedText);

  console.log(JSON.stringify({
    detailUrl: config.detailUrl,
    status: response ? response.status() : null,
    finalUrl: page.url(),
    previewResult,
    coverState,
    downloads: probeDownloads,
    consoleMessages: probeConsoleMessages,
    requestFailures: probeRequestFailures,
  }));
  await browser.close();
}

main().catch(async (error) => {
  const page = probePage;
  const diagnostics = {
    stage: probeStage,
    error: String(error),
    stack: error.stack,
    finalUrl: page ? page.url() : null,
    frames: page ? page.frames().map((frame) => ({name: frame.name(), url: frame.url()})) : [],
    consoleMessages: probeConsoleMessages,
    requestFailures: probeRequestFailures,
  };
  if (page && !page.isClosed()) {
    try {
      diagnostics.document = await Promise.race([
        page.evaluate(() => ({
          title: document.title,
          coverObserved: window.replayCoverObserved,
          replayObserved: window.replayPaintedObserved,
          coverPresent: !!document.getElementById('replay-screenshot-cover'),
          bodyText: document.body?.innerText.slice(0, 1000),
          frameSources: Array.from(document.querySelectorAll("iframe")).map((frame) => frame.src),
        })),
        new Promise((resolve) => setTimeout(() => resolve("document inspection timed out"), 2000)),
      ]);
    } catch (inspectionError) {
      diagnostics.document = String(inspectionError);
    }
  }
  console.error(JSON.stringify(diagnostics));
  if (probeBrowser) await probeBrowser.close();
  process.exit(1);
});
"""


def _seed_archive(data_dir: Path) -> dict[str, object]:
    script = textwrap.dedent(
        """
        import json
        import os
        from pathlib import Path
        from django.utils import timezone

        os.environ.setdefault("DJANGO_SETTINGS_MODULE", "archivebox.core.settings")
        import django
        django.setup()

        from django.contrib.auth import get_user_model
        from archivebox.core.models import Snapshot
        from archivebox.crawls.models import Crawl

        User = get_user_model()
        admin, _ = User.objects.get_or_create(
            username="testadmin",
            defaults={"email": "admin@example.com", "is_staff": True, "is_superuser": True},
        )
        admin.set_password("testpassword")
        admin.save()

        snapshots = {}
        fixture_specs = (
            ("attacker", "https://attacker.example/entry", "Attacker Snapshot", "ATTACKER_SECRET"),
            ("victim", "https://victim.example/private", "Victim Snapshot", "VICTIM_SECRET"),
        )

        for slug, url, title, secret in fixture_specs:
            crawl = Crawl.objects.create(
                urls=url,
                created_by=admin,
                status=Crawl.StatusChoices.SEALED,
                retry_at=timezone.now(),
            )
            snapshot = Snapshot.objects.create(
                url=url,
                title=title,
                crawl=crawl,
                status=Snapshot.StatusChoices.SEALED,
                downloaded_at=timezone.now(),
            )
            output_dir = Path(snapshot.output_dir)
            output_dir.mkdir(parents=True, exist_ok=True)
            (output_dir / "safe.json").write_text(
                json.dumps({"slug": slug, "secret": secret}),
                encoding="utf-8",
            )
            if slug == "attacker":
                (output_dir / "dangerous.html").write_text(
                    '''
                    <!doctype html>
                    <html>
                      <body>
                        <h1>Dangerous Replay Fixture</h1>
                        <script>
                          window.__dangerousScriptRan = true;
                          (async () => {
                            const params = new URLSearchParams(location.search);
                            const targets = {
                              own: params.get("own") || "safe.json",
                              victim: params.get("victim"),
                              admin: params.get("admin"),
                              api: params.get("api"),
                            };
                            const results = {};
                            for (const [label, url] of Object.entries(targets)) {
                              if (!url) continue;
                              try {
                                const response = await fetch(url, {credentials: "include"});
                                const text = await response.text();
                                results[label] = {
                                  ok: true,
                                  status: response.status,
                                  url: response.url,
                                  sample: text.slice(0, 120),
                                };
                              } catch (error) {
                                results[label] = {
                                  ok: false,
                                  error: String(error),
                                };
                              }
                            }
                            window.__probeResults = results;
                            const pre = document.createElement("pre");
                            pre.id = "probe-results";
                            pre.textContent = JSON.stringify(results);
                            document.body.appendChild(pre);
                          })().catch((error) => {
                            window.__probeResults = {fatal: String(error)};
                          });
                        </script>
                      </body>
                    </html>
                    ''',
                    encoding="utf-8",
                )
            snapshots[slug] = {
                "id": str(snapshot.id),
                "domain": snapshot.domain,
            }

        print(json.dumps({
            "username": "testadmin",
            "password": "testpassword",
            "snapshots": snapshots,
        }))
        """,
    )
    stdout, stderr, returncode = run_python_cwd(script, cwd=data_dir, timeout=120)
    assert returncode == 0, stderr
    return json.loads(stdout.strip())


def _build_probe_config(
    mode: str,
    port: int,
    fixture: dict[str, object],
    runtime: dict[str, Path | str],
) -> dict[str, str]:
    snapshots = fixture["snapshots"]
    attacker = snapshots["attacker"]
    victim = snapshots["victim"]
    base_origin = f"http://archivebox.localhost:{port}"
    attacker_id = attacker["id"]
    victim_id = victim["id"]

    if mode == "safe-subdomains-fullreplay":
        attacker_origin = f"http://{attacker_id}.archivebox.localhost:{port}"
        victim_url = f"http://{victim_id}.archivebox.localhost:{port}/safe.json"
        dangerous_base = f"{attacker_origin}/dangerous.html"
        admin_origin = f"http://admin.archivebox.localhost:{port}"
    else:
        attacker_origin = base_origin
        victim_url = f"{base_origin}/snapshot/{victim_id}/safe.json"
        dangerous_base = f"{base_origin}/snapshot/{attacker_id}/dangerous.html"
        admin_origin = base_origin

    query = urlencode(
        {
            "own": "safe.json",
            "victim": victim_url,
            "admin": f"{admin_origin}/admin/",
            "api": f"{admin_origin}/api/v1/docs",
        },
    )

    return {
        "mode": mode,
        "chromePath": str(runtime["chrome_binary"]),
        "adminLoginUrl": f"{admin_origin}/admin/login/",
        "dangerousUrl": f"{dangerous_base}?{query}",
        "username": fixture["username"],
        "password": fixture["password"],
    }


def _run_browser_probe(
    data_dir: Path,
    runtime: dict[str, Path | str],
    mode: str,
    fixture: dict[str, object],
    tmp_path: Path,
) -> dict[str, object]:
    port = get_free_port()
    server_env = os.environ.copy()
    server_env.pop("DATA_DIR", None)
    server_env.update(
        {
            "PYTHONPATH": str(Path(__file__).resolve().parents[2]),
            "BIND_ADDR": f"127.0.0.1:{port}",
            "BASE_URL": f"http://archivebox.localhost:{port}",
            "ALLOWED_HOSTS": "*",
            "SERVER_SECURITY_MODE": mode,
            "USE_COLOR": "False",
            "SHOW_PROGRESS": "False",
            "SAVE_ARCHIVEDOTORG": "False",
            "SAVE_TITLE": "False",
            "SAVE_FAVICON": "False",
            "SAVE_WGET": "False",
            "SAVE_WARC": "False",
            "SAVE_PDF": "False",
            "SAVE_SCREENSHOT": "False",
            "SAVE_DOM": "False",
            "SAVE_SINGLEFILE": "False",
            "SAVE_READABILITY": "False",
            "SAVE_MERCURY": "False",
            "SAVE_GIT": "False",
            "SAVE_YTDLP": "False",
            "SAVE_HEADERS": "False",
            "SAVE_HTMLTOTEXT": "False",
            "USE_CHROME": "False",
        },
    )
    server_log_path = tmp_path / f"{mode}_server.log"
    with server_log_path.open("w", encoding="utf-8") as server_log_file:
        process = run_archivebox_cmd(
            ["server", "--debug", "--nothreading", f"127.0.0.1:{port}"],
            cwd=data_dir,
            env=server_env,
            stdout=server_log_file,
            stderr=subprocess.STDOUT,
            start_new_session=True,
            wait=False,
        )
    try:
        supervisord_log_path = data_dir / "logs" / "supervisord.log"
        runserver_log_path = data_dir / "logs" / "worker_runserver.log"
        wait_for_log_pattern(
            supervisord_log_path,
            r"success: worker_runserver entered RUNNING state,",
            timeout=30,
        )
        deadline = time.monotonic() + 30
        last_exc: Exception | None = None
        while time.monotonic() < deadline:
            try:
                get_http_response(
                    port,
                    f"archivebox.localhost:{port}",
                    timeout=2,
                    process=process,
                )
                break
            except (AssertionError, requests.RequestException) as exc:
                last_exc = exc
                time.sleep(0.2)
        else:
            raise AssertionError(f"server did not become HTTP-ready: {last_exc}")
    except AssertionError as exc:
        stop_archivebox_process(process)
        server_log = server_log_path.read_text(encoding="utf-8", errors="replace")
        supervisord_log = supervisord_log_path.read_text(encoding="utf-8", errors="replace") if supervisord_log_path.exists() else ""
        runserver_log = runserver_log_path.read_text(encoding="utf-8", errors="replace") if runserver_log_path.exists() else ""
        raise AssertionError(
            f"{exc}\n\nSERVER LOG:\n{server_log}\n\nSUPERVISORD LOG:\n{supervisord_log}\n\nRUNSERVER LOG:\n{runserver_log}",
        ) from exc

    probe_path = tmp_path / "server_security_probe.js"
    probe_path.write_text(PUPPETEER_PROBE_SCRIPT, encoding="utf-8")
    probe_config = _build_probe_config(mode, port, fixture, runtime)

    env = os.environ.copy()
    env["NODE_PATH"] = str(runtime["node_path"])
    env["NODE_MODULES_DIR"] = str(runtime["node_modules_dir"])
    env["CHROME_BINARY"] = str(runtime["chrome_binary"])
    env["USE_COLOR"] = "False"

    try:
        result = subprocess.run(
            [str(runtime["node_binary"]), str(probe_path)],
            cwd=data_dir,
            env=env,
            input=json.dumps(probe_config),
            capture_output=True,
            text=True,
            timeout=120,
        )
    finally:
        stop_archivebox_process(process)
        server_log = server_log_path.read_text(encoding="utf-8", errors="replace")

    assert result.returncode == 0, f"{result.stderr}\n\nSERVER LOG:\n{server_log}"
    return json.loads(result.stdout.strip())


def _get_archivewebpage_capture(data_dir: Path, url: str) -> dict[str, str]:
    from archivebox.core.models import ArchiveResult, Snapshot
    from archivebox.tests.test_orm_helpers import use_archivebox_db

    with use_archivebox_db(data_dir):
        snapshot = Snapshot.objects.get(url=url)
        result = ArchiveResult.objects.get(
            snapshot=snapshot,
            plugin="archivewebpage",
            hook_name="on_Snapshot__65_archivewebpage_stop",
        )
        wacz_path = Path(snapshot.output_dir) / "archivewebpage" / "archivewebpage.wacz"
        assert snapshot.status == Snapshot.StatusChoices.SEALED
        assert result.status == ArchiveResult.StatusChoices.SUCCEEDED
        assert wacz_path.is_file()
        return {
            "snapshot_id": str(snapshot.id),
            "snapshot_path": snapshot.url_path,
            "result_id": str(result.id),
            "wacz_path": str(wacz_path),
        }


@pytest.mark.timeout(180)
def test_unconfigured_public_host_superuser_can_reach_setup_wizard(tmp_path: Path, browser_runtime) -> None:
    port = get_free_port()
    public_hostname = "archivebox.example.test"
    public_host = f"{public_hostname}:{port}"
    env = cli_env(
        port=port,
        disable_extractors=True,
        ALLOWED_HOSTS="*",
        BIND_ADDR=f"127.0.0.1:{port}",
    )
    env.pop("BASE_URL", None)
    env.pop("SERVER_SECURITY_MODE", None)
    init_result = run_archivebox_cmd(["init", "--quick"], cwd=tmp_path, env=env, timeout=60)
    assert init_result.returncode == 0, init_result.stderr or init_result.stdout

    process = start_daemon_server(
        tmp_path,
        port=port,
        env=env,
        daemonize=False,
        log_name="first_run_public_host.log",
